<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { BookOpen as BookIcon, Network as NetworkIcon } from '@lucide/vue';
import heroBanner from '../assets/medical/skill-management-banner.webp';
import { Layers, Box, Users, Zap, Clock, LayoutGrid, BarChart3, TrendingUp, Folder, Search, Pencil, Copy, Plus, ArrowRight, Ellipsis, CheckCircle, Settings2 } from '@lucide/vue';
import { FlaskConical, LoaderCircle, RefreshCw, Save, ShieldCheck, X } from '@lucide/vue';
import { getAdminSkills, getSkillCalls, testSkill, updateSkill } from '../api';
import type { SkillCall, SkillDefinition, SkillPolicy, SkillResult, SkillRole } from '../types';

const tab=ref('manage'),category=ref(''),search=ref(''),statusFilter=ref(''),roleFilter=ref(''),checked=ref<string[]>([]),addOpen=ref(false),editing=ref('');
interface Statistics {today_calls:number;total_calls:number;latest_update:string|null;per_skill:Array<{skill_id:string;total:number;successful:number;average_ms:number}>;trend:Array<{date:string;count:number}>}
const stats=ref<Statistics|null>(null);
const skills = ref<SkillDefinition[]>([]);
const calls = ref<SkillCall[]>([]);
const drafts = reactive<Record<string, SkillPolicy>>({});
const roles: { id: SkillRole; name: string }[] = [{ id: 'student', name: '学生' }, { id: 'teacher', name: '教师' }, { id: 'admin', name: '管理员' }];
const statuses: Record<string, string> = { success: '成功', empty: '无匹配', disabled: '未启用', forbidden: '无权限', rate_limited: '额度耗尽', error: '失败', running: '执行中' };
const loading = ref(false);
const saving = ref('');
const testing = ref(false);
const selectedId = ref('');
const query = ref('心脏');
const testResult = ref<SkillResult | null>(null);
const error = ref('');
const notice = ref('');

const filtered=computed(()=>skills.value.filter(s=>(!category.value||s.id===category.value)&&(!statusFilter.value||(statusFilter.value==='enabled')===drafts[s.id]?.enabled)&&(!roleFilter.value||drafts[s.id]?.allowed_roles.includes(roleFilter.value as SkillRole))&&`${s.name} ${s.description} ${s.id} ${s.version}`.toLowerCase().includes(search.value.toLowerCase())));
const enabledCount=computed(()=>skills.value.filter(s=>s.enabled).length);
const authorizedRoles=computed(()=>new Set(skills.value.filter(s=>s.enabled).flatMap(s=>s.allowed_roles)).size);
const allChecked=computed(()=>!!filtered.value.length&&filtered.value.every(s=>checked.value.includes(s.id)));
const presets=[{name:'学生自主学习',note:'启用能力并仅授权学生，每账号每小时 120 次',roles:['student'] as SkillRole[],limit:120},{name:'教师备课',note:'启用能力并授权教师、管理员，每小时 120 次',roles:['teacher','admin'] as SkillRole[],limit:120},{name:'管理员验证',note:'仅授权管理员，每账号每小时 30 次',roles:['admin'] as SkillRole[],limit:30}];
const icon=(id:string)=>id==='anatomy_search'?Search:id==='textbook_search'?BookIcon:NetworkIcon;
function toggleAll(){checked.value=allChecked.value?checked.value.filter(id=>!filtered.value.some(s=>s.id===id)):[...new Set([...checked.value,...filtered.value.map(s=>s.id)])];}
function preset(p:typeof presets[number]){if(!checked.value.length){notice.value='请先在能力管理中勾选需要应用模板的能力。';return;}for(const id of checked.value){if(drafts[id])drafts[id]={enabled:true,allowed_roles:[...p.roles],hourly_limit:p.limit};}notice.value='已应用到草稿，请逐项保存确认。';tab.value='permissions';}
async function copyConfig(s:SkillDefinition){try{await navigator.clipboard.writeText(JSON.stringify({id:s.id,version:s.version,...drafts[s.id]},null,2));notice.value='配置已复制';}catch{error.value='复制失败，请重试';}}
async function loadStats(){const token=localStorage.getItem('medical_auth_token');const r=await fetch(`${import.meta.env.VITE_API_BASE_URL||''}/api/admin/skills/statistics`,{headers:token?{Authorization:`Bearer ${token}`}:{}});if(!r.ok)throw new Error('调用统计读取失败');stats.value=await r.json();}
function draft(skill: SkillDefinition): SkillPolicy { return { enabled: skill.enabled, allowed_roles: [...skill.allowed_roles], hourly_limit: skill.hourly_limit }; }
function dirty(skill: SkillDefinition) {
  const value = drafts[skill.id];
  return value && (value.enabled !== skill.enabled || value.hourly_limit !== skill.hourly_limit || [...value.allowed_roles].sort().join() !== [...skill.allowed_roles].sort().join());
}
async function load() {
  loading.value = true;
  error.value = '';
  try {
    const result = await getAdminSkills();
    skills.value = result;
    result.forEach(skill => { drafts[skill.id] = draft(skill); });
    calls.value = (await getSkillCalls()).items;
    await loadStats();
  } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Skill 管理暂时不可用'; }
  finally { loading.value = false; }
}
async function save(skill: SkillDefinition) {
  if (saving.value) return;
  const p=drafts[skill.id];if(!Number.isInteger(p.hourly_limit)||p.hourly_limit<1||p.hourly_limit>1000){error.value='调用限额需为 1～1000 的整数';return;}if(p.enabled&&!p.allowed_roles.length){error.value='启用能力时至少选择一种角色';return;}
  saving.value = skill.id;
  error.value = ''; notice.value = '';
  try {
    const updated = await updateSkill(skill.id, drafts[skill.id]);
    skills.value = skills.value.map(item => item.id === skill.id ? updated : item);
    drafts[skill.id] = draft(updated);
    notice.value = `${skill.name}已保存`;
    await loadStats();
    testResult.value = null;
  } catch (reason) { error.value = reason instanceof Error ? reason.message : '保存失败'; }
  finally { saving.value = ''; }
}
function selectTest(id: string) { selectedId.value = id; testResult.value = null; }
async function runTest() {
  if (testing.value || !query.value.trim()) return;
  testing.value = true; error.value = ''; testResult.value = null;
  try {
    testResult.value = await testSkill(selectedId.value, { query: query.value.trim() });
    calls.value = (await getSkillCalls()).items;
    await loadStats();
  } catch (reason) { error.value = reason instanceof Error ? reason.message : '测试失败'; }
  finally { testing.value = false; }
}
onMounted(load);
</script>

<template>
<div class="skills-console">
 <section class="skills-hero" :style="{'--skills-banner':`url(${heroBanner})`}"><h1>Skill 管理</h1><p>配置教学所需的能力模块，管理工具、数据源与调用权限。</p></section>
 <div v-if="error" class="skill-notice error" role="alert">{{error}}<button @click="error=''">关闭</button></div><div v-if="notice" class="skill-notice" role="status">{{notice}}<button @click="notice=''">关闭</button></div>
 <section class="skills-metrics"><article><i><Layers :size="30"/></i><div><small>已配置 Skill</small><strong>{{loading&&!skills.length?'—':skills.length}}</strong></div></article><article><i><Box :size="30"/></i><div><small>可用能力</small><strong>{{enabledCount}}</strong></div></article><article><i><Users :size="30"/></i><div><small>已授权角色</small><strong>{{authorizedRoles}} <em>类</em></strong></div></article><article><i><Zap :size="30"/></i><div><small>今日调用次数</small><strong>{{stats?.today_calls ?? '—'}}</strong></div></article><article><i><Clock :size="30"/></i><div><small>最近更新时间</small><strong class="date-stat">{{stats?.latest_update?new Date(stats.latest_update).toLocaleString('zh-CN',{hour12:false}):'尚未配置'}}</strong></div></article></section>
 <nav class="skills-tabs"><button :class="{active:tab==='manage'}" @click="tab='manage'"><LayoutGrid :size="21"/>能力管理</button><button :class="{active:tab==='calls'}" @click="tab='calls'"><BarChart3 :size="21"/>调用记录</button><button :class="{active:tab==='stats'}" @click="tab='stats'"><TrendingUp :size="21"/>使用统计</button><button :class="{active:tab==='templates'}" @click="tab='templates'"><Layers :size="21"/>配置模板</button><button :class="{active:tab==='permissions'}" @click="tab='permissions'"><ShieldCheck :size="21"/>权限设置</button><button class="primary add-skill" @click="addOpen=true"><Plus :size="21"/>新增 Skill</button></nav>
 <div v-if="tab==='manage'||tab==='permissions'" class="skills-layout"><aside class="skills-panel skills-categories"><h2>能力分类</h2><button :class="{active:!category}" @click="category=''"><Layers :size="19"/><strong>全部能力</strong><span>{{skills.length}}</span></button><button v-for="s in skills" :key="s.id" :class="{active:category===s.id}" @click="category=s.id"><Folder :size="19"/><strong>{{s.name}}</strong><span>1</span></button></aside>
  <section class="skills-panel skills-list"><header><h2>{{tab==='permissions'?'权限设置':'能力列表'}}（{{filtered.length}}）</h2><button :disabled="loading||!!saving||testing" @click="load"><RefreshCw :size="16"/>刷新</button></header><div class="skills-filters"><label><Search :size="18"/><input v-model="search" placeholder="搜索 Skill 名称、描述或版本" aria-label="搜索 Skill"/></label><select v-model="statusFilter" aria-label="状态筛选"><option value="">状态：全部</option><option value="enabled">已启用</option><option value="disabled">已停用</option></select><select v-model="roleFilter" aria-label="角色筛选"><option value="">角色：全部</option><option v-for="r in roles" :key="r.id" :value="r.id">{{r.name}}</option></select></div>
  <div class="skills-table-scroll"><table class="skills-table"><thead><tr><th><input type="checkbox" :checked="allChecked" aria-label="全选当前能力" @change="toggleAll"/></th><th>Skill 名称</th><th>版本</th><th>能力描述</th><th>启用状态</th><th>允许角色</th><th>调用限额 / 小时</th><th>更新记录</th><th>操作</th></tr></thead><tbody><tr v-for="s in filtered" :key="s.id" :class="{changed:dirty(s)}"><td><input v-model="checked" :value="s.id" type="checkbox" :aria-label="'选择'+s.name"/></td><td><div class="skill-name"><i><component :is="icon(s.id)" :size="24"/></i><span><strong>{{s.name}}</strong><small>{{s.id}}</small></span></div></td><td><span class="version">v{{s.version}}</span></td><td class="skill-description">{{s.description}}<small>（{{s.source}}）</small></td><td><label class="skill-switch"><input v-model="drafts[s.id].enabled" type="checkbox" role="switch" :aria-label="s.name+'启用'" :disabled="loading||!!saving||testing"/><span/></label></td><td><div class="skill-roles"><label v-for="r in roles" :key="r.id" :class="{active:drafts[s.id].allowed_roles.includes(r.id)}"><input v-model="drafts[s.id].allowed_roles" :value="r.id" type="checkbox" :aria-label="s.name+'允许'+r.name" :disabled="loading||!!saving||testing"/><span>{{r.name}}</span></label></div></td><td><input v-model.number="drafts[s.id].hourly_limit" class="skill-limit" type="number" min="1" max="1000" :aria-label="s.name+'小时额度'" :disabled="loading||!!saving||testing"/></td><td class="skill-update"><small>{{s.updated_by||'尚未配置'}}</small><small v-if="s.updated_at">{{new Date(s.updated_at).toLocaleString('zh-CN',{hour12:false})}}</small><b v-if="dirty(s)">待保存</b></td><td><div class="skill-actions"><button :aria-label="'编辑'+s.name" :title="'编辑'+s.name" @click="editing=s.id"><Pencil :size="18"/></button><button :aria-label="'复制'+s.name+'配置'" title="复制配置" @click="copyConfig(s)"><Copy :size="18"/></button><button :aria-label="'测试'+s.name" title="测试" :disabled="testing||!!saving||dirty(s)" @click="selectTest(s.id)"><FlaskConical :size="18"/></button><button v-if="dirty(s)" :aria-label="'保存'+s.name" title="保存修改" :disabled="!!saving" @click="save(s)"><Save :size="18"/></button><button v-else :aria-label="'详情'+s.name" title="能力详情与权限" @click="editing=s.id"><Ellipsis :size="20"/></button></div></td></tr></tbody></table></div><p v-if="loading" class="empty">正在加载能力…</p><p v-else-if="!filtered.length" class="empty">暂无匹配能力，请调整筛选。</p><small v-if="skills.some(dirty)" class="draft-hint">启用状态、角色与限额尚有草稿修改，点击行末保存按钮后生效。</small></section>
 </div>
 <section v-else-if="tab==='calls'" class="skills-panel records-panel"><header><h2>调用记录（最近 {{calls.length}} 条）</h2><button :disabled="loading" @click="load"><RefreshCw :size="16"/>刷新</button></header><div class="skills-table-scroll"><table class="skills-table"><thead><tr><th>调用时间</th><th>Skill</th><th>账号 / 角色</th><th>结果</th><th>耗时</th><th>说明</th></tr></thead><tbody><tr v-for="c in calls" :key="c.id"><td>{{new Date(c.created_at).toLocaleString('zh-CN',{hour12:false})}}</td><td>{{skills.find(s=>s.id===c.skill_id)?.name||c.skill_id}}<small>{{c.skill_id}}</small></td><td>{{c.account}} · {{roles.find(r=>r.id===c.role)?.name||c.role}}</td><td><span class="call-status" :class="{success:c.status==='success'}">{{statuses[c.status]||c.status}}</span></td><td>{{c.duration_ms}} ms</td><td>{{c.message}}</td></tr></tbody></table></div><p v-if="!calls.length" class="empty">暂无调用记录</p></section>
 <section v-else-if="tab==='stats'" class="skills-panel statistics-panel"><header><h2>使用统计</h2><small>累计调用 {{stats?.total_calls ?? '—'}} 次 · 今日 {{stats?.today_calls ?? '—'}} 次</small></header><div class="stats-columns"><div><h3>近 7 天调用趋势</h3><div class="trend-bars"><div v-for="d in stats?.trend||[]" :key="d.date"><strong>{{d.count}}</strong><i :style="{height:`${Math.max(2,d.count/Math.max(1,...(stats?.trend||[]).map(t=>t.count))*120)}px`}"/><small>{{d.date.slice(5)}}</small></div></div></div><div><h3>能力使用情况</h3><div v-for="s in skills" :key="s.id" class="usage-row"><strong>{{s.name}}</strong><span>{{stats?.per_skill.find(c=>c.skill_id===s.id)?.total||0}} 次</span><small>成功 {{stats?.per_skill.find(c=>c.skill_id===s.id)?.successful||0}} 次</small></div></div></div></section>
 <section v-else class="skills-panel template-panel"><header><h2>配置模板</h2><span>已选 {{checked.length}} 个能力</span></header><p class="muted">模板修改所选能力的草稿，确认并保存后生效。</p><div class="preset-grid"><article v-for="p in presets" :key="p.name"><ShieldCheck :size="28"/><h3>{{p.name}}</h3><p>{{p.note}}</p><button @click="preset(p)">应用到所选能力 <ArrowRight :size="15"/></button></article></div></section>
 <section v-if="tab==='manage'||tab==='permissions'" class="skills-panel recent-calls"><header><h2><Clock :size="20"/>最近调用</h2><button @click="tab='calls'">查看全部记录 <ArrowRight :size="17"/></button></header><ol v-if="calls.length"><li v-for="c in calls.slice(0,3)" :key="c.id"><time>{{new Date(c.created_at).toLocaleString('zh-CN',{hour12:false})}}</time><span><strong>{{skills.find(s=>s.id===c.skill_id)?.name||c.skill_id}}</strong> · {{c.skill_id}}</span><span>{{roles.find(r=>r.id===c.role)?.name||c.role}}</span><span class="call-status" :class="{success:c.status==='success'}"><CheckCircle :size="15"/>{{statuses[c.status]||c.status}}（{{c.duration_ms}} ms）</span></li></ol><p v-else class="empty">暂无调用记录。测试能力或通过助教调用后，记录会显示在这里。</p></section>
 <Teleport to="body"><div v-if="selectedId||editing||addOpen" class="skills-overlay" @click.self="!testing&&!saving&&(selectedId='',editing='',addOpen=false)"><section class="skills-dialog" role="dialog" aria-modal="true" :aria-label="selectedId?'能力测试':editing?'能力配置':'接入新 Skill'"><header><h2>{{selectedId?(skills.find(s=>s.id===selectedId)?.name+' · 测试'):editing?(skills.find(s=>s.id===editing)?.name+' · 配置'):'接入新 Skill'}}</h2><button :disabled="testing||!!saving" aria-label="关闭" @click="selectedId='';editing='';addOpen=false"><X :size="20"/></button></header><p v-if="error" class="dialog-error" role="alert">{{error}}</p>
 <template v-if="selectedId"><form class="test-form" @submit.prevent="runTest"><label>检索词<input v-model="query" required maxlength="200" :disabled="testing"/></label><button class="primary" :disabled="testing||!!saving||!query.trim()"><LoaderCircle v-if="testing" class="skill-spin" :size="17"/><FlaskConical v-else :size="17"/>运行测试</button></form><div v-if="testResult" class="test-result" role="status"><strong>{{statuses[testResult.status]}} · {{testResult.duration_ms}} ms</strong><p>{{testResult.message}}</p><p v-for="citation in testResult.citations" :key="citation.reference">{{citation.reference}}</p><details v-if="Object.keys(testResult.data).length"><summary>查看检索结果</summary><pre>{{JSON.stringify(testResult.data,null,2)}}</pre></details></div></template>
 <template v-else-if="editing"><p class="muted">{{skills.find(s=>s.id===editing)?.description}} · {{skills.find(s=>s.id===editing)?.source}}</p><label class="dialog-check"><input v-model="drafts[editing].enabled" type="checkbox"/>启用能力</label><h3>允许角色</h3><label v-for="r in roles" :key="r.id" class="dialog-check"><input v-model="drafts[editing].allowed_roles" type="checkbox" :value="r.id"/>{{r.name}}</label><label class="limit-label">每账号调用限额 / 小时<input v-model.number="drafts[editing].hourly_limit" type="number" min="1" max="1000"/></label><footer><button :disabled="!!saving" @click="drafts[editing]=draft(skills.find(s=>s.id===editing)!);editing=''">取消并恢复</button><button class="primary" :disabled="!!saving||!dirty(skills.find(s=>s.id===editing)!)" @click="save(skills.find(s=>s.id===editing)!)"><Save :size="16"/>{{saving?'保存中…':'保存配置'}}</button></footer></template>
 <template v-else><p>当前可配置 {{skills.length}} 项已注册的预置能力。新增能力需要先完成服务端工具接入和权限审核，不能通过填写名称直接创建可执行工具。</p><p class="muted">您可以使用“配置模板”快速配置现有能力，或复制能力配置作为新工具接入时的参考。</p><button @click="addOpen=false;tab='templates'">查看配置模板 <ArrowRight :size="16"/></button></template>
 </section></div></Teleport>
</div>
</template>

<style scoped>
